import * as THREE from 'three';
import type { Human, HumanLib, Role } from './humans';
import * as P from './scenes_props';
import { lam } from './scenes_props';

/** Scene definition as generated by pipeline/scenes_build.py (public/data/scenes.json). */
export interface Egg { id: string; title: string; text: string }
export interface SceneDef {
  type: string; x?: number; y?: number; dir?: number; count?: number; sign?: string[]; path?: number[][]; egg?: Egg;
  kind?: string; color?: string; run?: boolean; dog?: boolean; scale?: number;
}
export interface Ctx { lib: HumanLib; ground: (x: number, y: number) => number }
export interface Built {
  obj: THREE.Group; humans: Human[];
  /** world-space scene (paths): the group is not translated/rotated by the manager */
  world?: boolean;
  tick?: (dt: number) => void;
  extras?: { mixer: THREE.AnimationMixer }[];
}

const PI = Math.PI;
const faceTo = (fx: number, fz: number, tx: number, tz: number) => Math.atan2(-(tx - fx), -(tz - fz));

class B {
  readonly obj = new THREE.Group();
  readonly humans: Human[] = [];
  readonly extras: { mixer: THREE.AnimationMixer }[] = [];
  private k: number;
  private g0: number;
  private cs: number; private sn: number;
  constructor(private s: SceneDef, private ctx: Ctx) {
    this.k = Math.abs(Math.floor((s.x ?? s.path?.[0][0] ?? 0) * 7 + (s.y ?? s.path?.[0][1] ?? 0) * 13));
    const d = s.dir ?? 0; this.cs = Math.cos(d); this.sn = Math.sin(d);
    this.g0 = ctx.ground(s.x ?? 0, s.y ?? 0);
  }
  /** terrain offset of a local point relative to the scene origin */
  dy(lx: number, lz: number): number {
    const x = this.s.x ?? 0, y = this.s.y ?? 0;
    return this.ctx.ground(x + lx * this.cs - lz * this.sn, y - lx * this.sn - lz * this.cs) - this.g0;
  }
  put<T extends THREE.Object3D>(o: T, lx: number, lz: number, ry = 0, y = 0): T {
    o.position.set(lx, this.dy(lx, lz) + y, lz); o.rotation.y = ry; this.obj.add(o); return o;
  }
  human(lx: number, lz: number, ry: number, anim = 'idle', acc: string[] = [], t = 0, role: Role = 'any'): Human {
    const ad = this.ctx.lib.adults, h = this.ctx.lib.instance(ad[(this.k++ * 5 + 3) % ad.length]);
    this.ctx.lib.dress(h, role);
    this.put(h.root, lx, lz, ry);
    if (anim !== 'idle') h.play(anim, 0);
    h.mixer.setTime(t || (this.humans.length * 0.37));
    for (const a of acc) this.ctx.lib.attach(h, a);
    this.humans.push(h);
    return h;
  }
  lying(lx: number, lz: number, ry: number) {
    const ad = this.ctx.lib.adults, h = this.ctx.lib.instance(ad[(this.k++ * 5 + 3) % ad.length]), wrap = new THREE.Group();
    h.root.rotation.x = PI / 2; h.root.position.set(0, 0.12, -0.8);
    wrap.add(h.root); this.put(wrap, lx, lz, ry); this.humans.push(h);
  }
  done(extra: Partial<Built> = {}): Built { return { obj: this.obj, humans: this.humans, extras: this.extras, ...extra }; }
  get ground() { return this.ctx.ground; }
  get lib() { return this.ctx.lib; }
}

export function build(s: SceneDef, ctx: Ctx): Built | null {
  const b = new B(s, ctx);
  const fn = BUILDERS[s.type];
  return fn ? fn(b, s) : null;
}

type Fn = (b: B, s: SceneDef) => Built;

function queue(b: B, s: SceneDef, n = s.count ?? 20) {
  for (let i = 0; i < n; i++) {
    const j = (i * 37 % 10) / 25;
    b.human(j, -(i * 0.75 + j), PI + (j - 0.2), i % 3 === 1 ? 'stand_phone' : 'idle', i % 4 === 2 ? ['shoulder_bag'] : [], i * 0.37);
  }
  if (s.sign) b.put(P.signBoard(s.sign), 0.9, 1.0, 0);
}

const BUILDERS: Record<string, Fn> = {
  queue: (b, s) => { queue(b, s); return b.done(); },
  atm: (b, s) => { queue(b, s, s.count ?? 3); return b.done(); },
  clubqueue: (b, s) => {
    queue(b, s, s.count ?? 8);
    b.put(P.barrier(), 0, 0.5, 0); b.put(P.barrier(), 0, -2.4, 0); b.put(P.barrier(), 0, -5, 0);
    return b.done();
  },
  preacher: (b, s) => { b.human(0, 0, 0); if (s.sign) b.put(P.signBoard(s.sign, 0.6, 0.8), 0, -0.8, 0); return b.done(); },
  musician: (b, s) => {
    b.human(0, 0, 0, 'idle', s.kind === 'sax' ? [] : ['tote_bag']);
    if (s.sign) b.put(P.signBoard(s.sign, 0.6, 0.8), 1.2, -0.6, 0);
    const g = new THREE.Group();
    g.add(new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.35, 0.25), lam(0x1a1a1a)), new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.06, 1.0), lam(0x7a1f24)));
    g.children[0].position.set(0.6, 0.18, 0); g.children[1].position.set(0, 0.03, -0.9);
    b.put(g, 0, 0);
    const inst = s.kind === 'accordion' ? new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.3, 0.3), lam(0xb0202a))
      : s.kind === 'sax' ? new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.09, 0.8, 8), lam(0xd8a52a))
      : new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.9, 0.3), lam(0x9a5a2a));
    inst.position.set(0, 1.1, -0.3); if (s.kind !== 'accordion') inst.rotation.z = 0.5;
    const ig = new THREE.Group(); ig.add(inst); b.put(ig, 0, 0);
    return b.done();
  },
  picnic: (b, s) => {
    const bl = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.02, 1.6), lam(0xc8443a)); b.put(bl, 0, 0, 0, 0.02);
    for (let i = 0; i < (s.count ?? 4); i++) b.lying((i - 2) * 1.1, (i % 2) * 1.8, (i % 2) * PI);
    return b.done();
  },
  kiosk: (b, s) => { if (s.sign) b.put(P.signBoard(s.sign, 0.9, 1.1), 0, 0); return b.done(); },
  luxemburgerli: (b) => { b.put(P.chocBox(), 0, 0); return b.done(); },
  boeoegg: (b, s) => { const o = P.miniBoegg(s.scale ?? 1); b.put(o, 0, 0); return b.done(); },
  miniboeoegg: (b, s) => { b.put(P.miniBoegg(s.scale ?? 0.3), 0, 0); return b.done(); },
  duck: (b) => { b.put(P.duck(), 0, 0); return b.done(); },
  glove: (b) => { b.put(P.glove(), 0, 0); return b.done(); },
  planter: (b) => { b.put(P.planter(), 0, 0); return b.done(); },
  menu: (b, s) => { b.put(P.menuBoard(s.sign ?? ['TAGESMENÜ']), 0, 0); return b.done(); },
  umzug: (b) => {
    b.put(P.movingBoxes(), 0, 0);
    b.human(-1.2, -1.2, faceTo(-1.2, -1.2, 2, 0), 'stand_phone');
    return b.done();
  },
  art: (b, s) => { b.put(P.plaque(s.sign ?? ['Kunst']), 1.4, 0.6); return b.done(); },
  graffiti: (b, s) => { b.put(P.graffitiWall(s.sign ?? ['HIER KÖNNTE', 'IHRE WOHNUNG', 'STEHEN'], s.color ?? '#ff3d7f'), 0, 0); return b.done(); },
  flohmarkt: (b, s) => {
    b.put(P.vinylStall(), 0, 0);
    b.human(0.3, 0.9, 0); b.human(-0.8, -1.0, PI, 'stand_phone', ['tote_bag']);
    if (s.sign) b.put(P.signBoard(s.sign, 0.6, 0.7), 1.5, -0.6, 0);
    return b.done();
  },
  pingpong: (b) => {
    b.put(P.pingpongTable(), 0, 0);
    b.human(0, 1.9, 0); b.human(0, -1.9, PI);
    const ball = new THREE.Mesh(new THREE.SphereGeometry(0.02, 6, 5), lam(0xffffff)); b.obj.add(ball);
    let t = 0;
    return b.done({ tick: (dt) => { t += dt; const p = (t % 1.1) / 1.1, dir = Math.floor(t / 1.1) % 2 ? -1 : 1; ball.position.set(Math.sin(t * 2) * 0.3, 0.9 + Math.sin(p * PI) * 0.22, dir * (1.3 - 2.6 * p)); } });
  },
  boccia: (b) => {
    const cols = [0xc8443a, 0xc8443a, 0xc8443a, 0x2f6b9a, 0x2f6b9a, 0x2f6b9a];
    b.put(P.boule(0xf0e060), 0, -6);
    cols.forEach((c, i) => b.put(P.boule(c), (i % 3 - 1) * 0.6 + (i > 2 ? 0.25 : 0), -5.2 - (i % 3) * 0.35));
    b.human(-0.6, 0.6, 0, 'idle'); b.human(0.7, 0.8, 0.1); b.human(2.2, -2.2, faceTo(2.2, -2.2, 0, -6));
    return b.done();
  },
  badi: (b, s) => {
    const cols = [0x2f9ad8, 0xe0553a, 0xf0c030, 0x6ac07a];
    cols.slice(0, s.count ?? 3).forEach((c, i) => b.put(P.towel(c), (i - 1) * 1.5, (i % 2) * 0.5, (i - 1) * 0.15));
    b.put(P.parasol(), 1.6, -0.9);
    b.lying(-1.5, 0.3, 0.1);
    return b.done();
  },
  tech: (b) => {
    b.human(0, 0, faceTo(0, 0, 0.9, -0.2), 'idle', ['shoulder_bag']);
    b.human(0.9, -0.2, faceTo(0.9, -0.2, 0, 0), 'idle');
    b.human(0.4, 0.9, faceTo(0.4, 0.9, 0.4, -0.1), 'stand_phone');
    return b.done();
  },
  tourists: (b) => {
    b.human(0, 0, 0, 'idle', ['umbrella_closed']);
    b.put(P.flag(0xe03a3a), 0.55, -0.2);
    for (let i = 0; i < 5; i++) {
      const a = (i - 2) * 0.55, lx = Math.sin(a) * 2.2; // semi-circle in front of the guide
      const fz = -Math.cos(a) * 2.2;
      b.human(lx, fz, faceTo(lx, fz, 0, 0), i % 2 ? 'stand_phone' : 'idle', i === 1 ? ['backpack'] : i === 3 ? ['shoulder_bag'] : []);
    }
    return b.done();
  },
  selfie: (b) => {
    b.human(-0.6, 0, faceTo(-0.6, 0, 0, -1.2), 'stand_phone'); b.human(0.6, 0.1, faceTo(0.6, 0.1, 0, -1.2), 'stand_phone'); b.human(0, 0.7, faceTo(0, 0.7, 0, -1.2), 'idle');
    return b.done();
  },
  couriers: (b) => {
    for (let i = 0; i < 3; i++) { b.put(P.bikeProp([0x2a6fb0, 0xd0402a, 0x2a2a2a][i], true), i * 1.5 - 1.5, -1.2, PI / 2 + i * 0.2); b.human(i * 1.5 - 1.5 + (i - 1) * 0.3, 0.2, i === 1 ? PI : 0, 'idle', ['backpack'], 0, 'courier'); }
    return b.done();
  },
  cargo: (b) => {
    b.put(P.cargoBike(), 0, 0, 0.3);
    const dog = b.lib.spawnFree('dog_small');
    if (dog) { dog.obj.position.set(0.1, 0.34, -0.7); dog.obj.scale.setScalar(0.7); dog.mixer.timeScale = 0; dog.mixer.update(0.3); b.obj.add(dog.obj); }
    b.human(1.2, 0.4, PI * 1.3, 'idle', ['tote_bag']);
    return b.done();
  },
  jass: (b, s) => {
    const t = new THREE.Group();
    t.add(new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.06, 0.8), lam(0x7a5a3a)));
    t.children[0].position.y = 0.76;
    for (const [x, z] of [[-0.65, -0.3], [0.65, -0.3], [-0.65, 0.3], [0.65, 0.3]]) { const l = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.75, 0.06), lam(0x5a4a3a)); l.position.set(x, 0.37, z); t.add(l); }
    if (s.kind === 'fondue') { const pot = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.12, 0.14, 10), lam(0xb85a2a)); pot.position.y = 0.86; t.add(pot); }
    else for (let i = 0; i < 4; i++) { const c = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.005, 0.09), lam(0xf4f4ec)); c.position.set((i - 1.5) * 0.12, 0.8, 0.0); t.add(c); }
    b.put(t, 0, 0);
    for (const [x, z] of [[-0.5, -0.85], [0.5, -0.85], [-0.5, 0.85], [0.5, 0.85]]) b.human(x, z, faceTo(x, z, 0, 0));
    return b.done();
  },
  toeggeli: (b) => {
    b.put(P.foosball(), 0, 0);
    b.human(-0.95, 0, faceTo(-0.95, 0, 0, 0)); b.human(0.95, 0, faceTo(0.95, 0, 0, 0));
    return b.done();
  },
  pigeons: (b, s) => {
    const birds: { g: THREE.Group; ph: number }[] = [];
    for (let i = 0; i < (s.count ?? 5); i++) { const g = P.pigeon(); b.put(g, Math.cos(i * 2.1) * (0.5 + i * 0.25), Math.sin(i * 2.1) * (0.5 + i * 0.25), i * 1.3); birds.push({ g, ph: i * 0.9 }); }
    let t = 0;
    return b.done({ tick: (dt) => { t += dt; for (const p of birds) { const head = p.g.userData.head as THREE.Object3D; head.position.y = 0.17 - Math.max(0, Math.sin(t * 5 + p.ph)) * 0.09; head.position.z = -0.1 - Math.max(0, Math.sin(t * 5 + p.ph)) * 0.04; } } });
  },
  eggonly: (b) => b.done(),
  sign: (b, s) => { b.put(P.signBoard(s.sign ?? ['']), 0, 0); return b.done(); },
  velos: (b, s) => {
    const cols = [0x2a6fb0, 0xd0402a, 0x2a2a2a, 0x3a8a5a, 0xe0b040];
    for (let i = 0; i < (s.count ?? 4); i++) b.put(P.bikeProp(cols[(i * 3 + 1) % cols.length], i % 2 === 0), 1.2 + i * 0.75, 0.3, PI / 2 + (i % 3) * 0.08);
    if (s.sign) b.put(P.signBoard(s.sign, 0.7, 0.8), 0, 0);
    return b.done();
  },
  plausch: (b, s) => {
    const n = s.count ?? 3;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * PI * 2, lx = Math.sin(a) * 0.95, lz = Math.cos(a) * 0.95;
      b.human(lx, lz, faceTo(lx, lz, 0, 0), i % 3 === 1 ? 'stand_phone' : 'idle', i === 0 ? ['tote_bag'] : i === 2 ? ['shopping_bag'] : [], i * 0.9);
    }
    if (s.sign) b.put(P.signBoard(s.sign, 0.6, 0.7), 1.8, -0.4, 0);
    return b.done();
  },
  stilts: (b, s) => pathWalker(b, s, true),
  walker: (b, s) => pathWalker(b, s, false),
};

function pathWalker(b: B, s: SceneDef, stilts: boolean): Built {
  const P_ = s.path!;
  const root = new THREE.Group(), h = b.lib.instance(b.lib.adults[Math.floor(Math.abs(P_[0][0]) + 3) % b.lib.adults.length]);
  b.humans.push(h); b.lib.dress(h, s.kind === 'courier' ? 'courier' : 'any');
  let dog: { obj: THREE.Object3D; mixer: THREE.AnimationMixer } | null = null;
  if (stilts) {
    for (const name of ['foot_l', 'foot_r']) {
      const bone = h.root.getObjectByName(name);
      if (!bone) continue;
      const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.03, 0.03, 1.1, 6), lam(0x6b4a2a));
      pole.position.y = -0.55; bone.add(pole);
    }
    h.root.position.y = 1.05;
  } else {
    if (s.dog) { dog = b.lib.spawnFree(Math.abs(P_[0][1]) % 2 < 1 ? 'dog_small' : 'dog_medium'); if (dog) { b.lib.attach(h, dog.obj.name.includes('small') ? 'leash_small' : 'leash_medium'); b.extras.push(dog); b.obj.add(dog.obj); } }
    else b.lib.attach(h, s.kind === 'courier' ? 'backpack' : 'shopping_bag');
  }
  root.add(h.root); b.obj.add(root);
  const speed = s.run ? 3.4 : stilts ? 1.2 : 1.1;
  h.setSpeed(speed);
  let seg = 0, t = 0, d = 1;
  const tick = (dt: number) => {
    const a = P_[seg], e = P_[seg + 1], len = Math.hypot(e[0] - a[0], e[1] - a[1]) || 1;
    t += (d * speed * dt) / len;
    if (t > 1 || t < 0) { const n = seg + d; if (n < 0 || n >= P_.length - 1) { d = -d; t = Math.min(1, Math.max(0, t)); } else { seg = n; t = d > 0 ? 0 : 1; } }
    const c = P_[seg], f = P_[seg + 1], px = c[0] + (f[0] - c[0]) * t, py = c[1] + (f[1] - c[1]) * t;
    root.position.set(px, b.ground(px, py), -py);
    const hd = Math.atan2((f[0] - c[0]) * d, (f[1] - c[1]) * d);
    root.rotation.y = -hd;
    if (dog) {
      const sx = Math.cos(hd) * 0.6 + Math.sin(hd) * 0.9, sy = -Math.sin(hd) * 0.6 + Math.cos(hd) * 0.9;
      dog.obj.position.set(px + sx, b.ground(px + sx, py + sy), -(py + sy)); dog.obj.rotation.y = -hd;
    }
  };
  tick(0);
  return b.done({ world: true, tick });
}
